        given()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .post("/reservations/" + reservationId + "/check-in")
            .then()
            .statusCode(200);

        given()
            .post("/reservations/" + reservationId + "/check-out")
            .then()
            .statusCode(200)
            .body("title", is("Fatura de hospedagem"))
            .body("text", containsString("Fatura de hospedagem nº"))
            .body("text", containsString("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"))
            .body("text", containsString("Hóspede: Ana Souza"))
            .body("text", containsString("ISS retido (5%): R$ 38,99"));
    }

    @Test
    public void testPassportDocument() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "201");
        request.put("guestName", "John Smith");
        request.put("guestEmail", "john@example.com");
        request.put("guestPassport", "X1234567");
        request.put("guestCountry", "United Kingdom");
        request.put("checkIn", "2027-03-10");
        request.put("checkOut", "2027-03-12");
        request.put("guests", 2);
        request.put("ratePlan", "STANDARD");

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .post("/reservations/" + reservationId + "/check-in")
            .then()
            .statusCode(200);

        given()
            .post("/reservations/" + reservationId + "/check-out")
            .then()
            .statusCode(200)
            .body("title", is("Booking receipt"))
            .body("text", containsString("Booking receipt no."))
            .body("text", containsString("Guest: John Smith (passport X1234567, United Kingdom)"))
            .body("text", containsString("Room: 201 (DELUXE)"))
            .body("text", containsString("Check-in: 2027-03-10 | Check-out: 2027-03-12 | 2 nights"))
            .body("text", containsString("Nights: BRL 779.80"))
            .body("text", containsString("Total: BRL 779.80"));
    }

    @Test
    public void testGetDocument() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "101");
        request.put("guestName", "Test User");
        request.put("guestEmail", "test@example.com");
        request.put("guestCpf", "99988877766");
        request.put("checkIn", "2027-05-10");
        request.put("checkOut", "2027-05-11");
        request.put("guests", 1);
        request.put("ratePlan", "STANDARD");

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .get("/reservations/" + reservationId + "/document")
            .then()
            .statusCode(409)
            .body("error", is("OPERATION_NOT_ALLOWED"));

        given()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        given()
            .get("/reservations/" + reservationId + "/document")
            .then()
            .statusCode(200)
            .body("title", is("Comprovante de reserva"))
            .body("text", containsString("Test User"));
    }
}

