package br.com.mareaalta;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

public class ReportsIT {

    @BeforeAll
    public static void setup() {
        if (RestAssured.port == RestAssured.UNDEFINED_PORT) {
            RestAssured.port = 7070;
            RestAssured.baseURI = "http://localhost";

            new Thread(() -> App.main(new String[]{})).start();

            try {
                Thread.sleep(2000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    @Test
    public void testOccupancyReport() {
        Map<String, Object> request1 = new HashMap<>();
        request1.put("roomNumber", "101");
        request1.put("guestName", "Guest 1");
        request1.put("guestEmail", "guest1@example.com");
        request1.put("guestCpf", "11111111111");
        request1.put("checkIn", "2027-06-10");
        request1.put("checkOut", "2027-06-12");
        request1.put("guests", 1);
        request1.put("ratePlan", "STANDARD");

        int id1 = given()
            .contentType(ContentType.JSON)
            .body(request1)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given().post("/reservations/" + id1 + "/confirmation");

        Map<String, Object> request2 = new HashMap<>();
        request2.put("roomNumber", "201");
        request2.put("guestName", "Guest 2");
        request2.put("guestEmail", "guest2@example.com");
        request2.put("guestCpf", "22222222222");
        request2.put("checkIn", "2027-06-09");
        request2.put("checkOut", "2027-06-11");
        request2.put("guests", 2);
        request2.put("ratePlan", "STANDARD");

        int id2 = given()
            .contentType(ContentType.JSON)
            .body(request2)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given().post("/reservations/" + id2 + "/confirmation");

        String csv = given()
            .get("/reports/occupancy?date=2027-06-10")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .extract()
            .asString();

        assert csv.contains("room,type,reservation,check_in,check_out");
        assert csv.contains("101,STANDARD," + id1 + ",2027-06-10,2027-06-12");
        assert csv.contains("201,DELUXE," + id2 + ",2027-06-09,2027-06-11");
        assert csv.contains("total,2/5");
    }

    @Test
    public void testRevenueReport() {
        Map<String, Object> request1 = new HashMap<>();
        request1.put("roomNumber", "102");
        request1.put("guestName", "Revenue Guest 1");
        request1.put("guestEmail", "revenue1@example.com");
        request1.put("guestCpf", "33333333333");
        request1.put("checkIn", "2027-08-15");
        request1.put("checkOut", "2027-08-17");
        request1.put("guests", 2);
        request1.put("ratePlan", "STANDARD");

        int id1 = given()
            .contentType(ContentType.JSON)
            .body(request1)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given().post("/reservations/" + id1 + "/confirmation");

        Map<String, Object> request2 = new HashMap<>();
        request2.put("roomNumber", "202");
        request2.put("guestName", "Revenue Guest 2");
        request2.put("guestEmail", "revenue2@example.com");
        request2.put("guestCpf", "44444444444");
        request2.put("checkIn", "2027-08-20");
        request2.put("checkOut", "2027-08-22");
        request2.put("guests", 2);
        request2.put("ratePlan", "NON_REFUNDABLE");

        int id2 = given()
            .contentType(ContentType.JSON)
            .body(request2)
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given().post("/reservations/" + id2 + "/confirmation");
        given().post("/reservations/" + id2 + "/cancellation");

        String csv = given()
            .get("/reports/revenue?month=2027-08")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .extract()
            .asString();

        assert csv.contains("reservation,room,check_in,check_out,status,amount");
        assert csv.contains(id1 + ",102,2027-08-15,2027-08-17,CONFIRMED,499.80");
        assert csv.contains(id2 + ",202,2027-08-20,2027-08-22,CANCELLED,662.83");
        assert csv.contains("total,1162.63");
    }
}

